(()=>{const stage=document.querySelector('.stage'),story=document.querySelector('.story'),reduce=matchMedia('(prefers-reduced-motion: reduce)');const start=performance.now();const clamp=x=>Math.max(0,Math.min(1,x));const ease=x=>{x=clamp(x);return x*x*(3-2*x)};let frame=0;function paint(){frame=0;const elapsed=performance.now()-start;const hero=1;const p=reduce.matches?0:ease(-story.getBoundingClientRect().top/Math.max(1,story.offsetHeight-stage.clientHeight));stage.style.setProperty('--draw',1.01*(1-clamp(elapsed/1400)));stage.style.setProperty('--intro',0);stage.style.setProperty('--logo-fill',reduce.matches?1:ease((elapsed-1400)/450));stage.style.setProperty('--hero',hero);stage.style.setProperty('--panels',hero);stage.style.setProperty('--p',p);document.querySelectorAll('.panel').forEach(a=>a.inert=hero<.9);if(elapsed<2200&&!reduce.matches)schedule()}function schedule(){if(!frame)frame=requestAnimationFrame(paint)}addEventListener('scroll',schedule,{passive:true});addEventListener('resize',schedule);reduce.addEventListener('change',schedule);paint()})();

